<section class="auth-card"><h1>Request an account</h1><form method="post" action="<?= dts_escape(site_url('registrations')) ?>" class="form-grid"><label>First name<input name="firstname" maxlength="100" required></label><label>Last name<input name="lastname" maxlength="100" required></label><label>Middle name<input name="middlename" maxlength="100"></label><label>Username<input name="username" maxlength="150" required></label><label>Position title<input name="position_title" maxlength="100"></label><label>Requested role<select name="requested_role_id" required><?php foreach ($roles as $role): ?><option value="<?= dts_escape($role['role_id']) ?>"><?= dts_escape($role['role_name']) ?></option><?php endforeach; ?></select></label><label>Password<input type="password" name="password" maxlength="255" required></label><label>Remarks<textarea name="applicant_remarks"></textarea></label><button type="submit">Submit request</button></form></section>
